/** Formatting helpers extracted from src/legacy/helpers.ts. */

import { UNIT_TABLE } from '../generated/types';
import { MS_PER_SECOND } from './parse';

export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) return '0s';
  const totalSeconds = Math.floor(ms / MS_PER_SECOND);
  const h = Math.floor(totalSeconds / 3600);
  const m = Math.floor((totalSeconds % 3600) / 60);
  const s = totalSeconds % 60;
  const parts: string[] = [];
  if (h) parts.push(`${h}h`);
  if (m) parts.push(`${m}m`);
  if (s || parts.length === 0) parts.push(`${s}s`);
  return parts.join(' ');
}

export function formatBytes(bytes: number, precision = 1): string {
  if (!Number.isFinite(bytes) || bytes < 0) return '0 B';
  if (bytes < 1024) return `${bytes} B`;
  let value = bytes;
  let i = 0;
  while (value >= 1024 && i < UNIT_TABLE.length - 1) {
    value /= 1024;
    i += 1;
  }
  return `${value.toFixed(precision)} ${UNIT_TABLE[i]}`;
}

